import{_ as e,c as a,o as r,b0 as s}from"./chunks/framework.Becqh7-x.js";const i="/linux-dev-docs/assets/images_04_04.aslFCIGV.svg",n="/linux-dev-docs/assets/images_04_05.BZ5mrwi0.svg",l="/linux-dev-docs/assets/image-20220727181412555.CNHbeQlH.png",u=JSON.parse('{"title":"LV020-CortexA寄存器组","description":null,"frontmatter":{"title":"LV020-CortexA寄存器组","date":"2026-01-06T14:50:07.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/platform/cortexA7/126d2c6e0cef18de666e1af3","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-01-06T14:50:07.397Z","fulluuid":"e666e1af366040268a594242fd7e0bc3","useduuid":"e666e1af3"}},"headers":[],"relativePath":"sdoc/platform/cortexA7/126d2c6e0cef18de666e1af3.md","filePath":"sdoc/10-开发平台/10-Cortex-A7/LV020-CortexA寄存器组.md","lastUpdated":1768604092000}'),o={name:"sdoc/platform/cortexA7/126d2c6e0cef18de666e1af3.md"};function d(p,t,c,R,g,h){return r(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="lv020-cortexa寄存器组" tabindex="-1">LV020-CortexA寄存器组 <a class="header-anchor" href="#lv020-cortexa寄存器组" aria-label="Permalink to &quot;LV020-CortexA寄存器组&quot;">​</a></h1><p>本节主要参考《<a href="https://developer.arm.com/documentation/den0013/0400/ARM-Processor-Modes-and-Registers" target="_blank" rel="noreferrer">ARM Cortex-A Series (Armv7-A) Programmer’s Guide</a>》的“第 3 章 ARM Processor Modes And Registers”。</p><h2 id="一、cortex-a寄存器组" tabindex="-1">一、Cortex-A寄存器组 <a class="header-anchor" href="#一、cortex-a寄存器组" aria-label="Permalink to &quot;一、Cortex-A寄存器组&quot;">​</a></h2><p>ARM 架构提供了 16 个 32 位的通用寄存器(R0~R15)供软件使用，前 15 个(R0~R14)可以用作通用的数据存储， R15 是程序计数器 PC，用来保存将要执行的指令。 ARM 还提供了一个当前程序状态寄存器 CPSR 和一个备份程序状态寄存器 SPSR， SPSR 寄存器就是 CPSR 寄存器的备份。</p><p><img src="'+i+'" alt="images_04_04"></p><blockquote><p>这张图参考：<a href="https://developer.arm.com/documentation/den0013/0400/ARM-Processor-Modes-and-Registers/Registers" target="_blank" rel="noreferrer">ARM Cortex-A Series (Armv7-A) Programmer’s Guide——Registers</a></p></blockquote><p>上一节的笔记已经了解到 Cortex-A7 有 9 种运行模式，每一种运行模式都有一组与之对应的寄存器组。每一种模式可见的寄存器包括 15 个通用寄存器(R0~R14)、一两个程序状态寄存器和一个程序计数器 PC。在这些寄存器中，有些是所有模式所共用的同一个物理寄存器，有一些是各模式自己所独立拥有的，各个模式所拥有的寄存器如下表：</p><p><img src="'+n+`" alt="images_04_05"></p><p>浅色字体的是与 User 模式所共有的寄存器，蓝绿色背景的是各个模式所独有的寄存器。可以看出，在所有的模式中，低寄存器组(R0~R7)是共享同一组物理寄存器的，只是一些高寄存器组在不同的模式有自己独有的寄存器，比如 FIQ 模式下 R8~R14 是独立的物理寄存器。假如某个程序在 FIQ 模式下访问 R13 寄存器，那它实际访问的是寄存器 R13_fiq，如果程序处于 SVC 模式下访问 R13 寄存器，那它实际访问的是寄存器 R13_svc。</p><blockquote><p>总结一下， CortexA 内核寄存器组成如下： （1）34 个通用寄存器（未备份寄存器，即 R0~R7；备份寄存器，即 R8~R14；），包括 R15 程序计数器(PC)和程序状态寄存器，这些寄存器都是 32 位的。</p><p>（2）8 个状态寄存器，包括 CPSR 和 SPSR。</p><p>（3）Hyp 模式下独有一个 ELR_Hyp 寄存器。</p></blockquote><h2 id="二、寄存器说明" tabindex="-1">二、寄存器说明 <a class="header-anchor" href="#二、寄存器说明" aria-label="Permalink to &quot;二、寄存器说明&quot;">​</a></h2><h3 id="_1-未备份寄存器" tabindex="-1">1. 未备份寄存器 <a class="header-anchor" href="#_1-未备份寄存器" aria-label="Permalink to &quot;1. 未备份寄存器&quot;">​</a></h3><p>未备份寄存器指的是 R0~R7。因为在所有的运行模式下 R0~R7 寄存器都是同一个物理寄存器，在不同的模式下， R0~R7 寄存器中的数据就会被破坏，所以 R0~R7这8个寄存器并没有被用作特殊用途。</p><h3 id="_2-备份寄存器" tabindex="-1">2. 备份寄存器 <a class="header-anchor" href="#_2-备份寄存器" aria-label="Permalink to &quot;2. 备份寄存器&quot;">​</a></h3><h4 id="_2-1-r8-r12" tabindex="-1">2.1 R8~R12 <a class="header-anchor" href="#_2-1-r8-r12" aria-label="Permalink to &quot;2.1 R8\\~R12&quot;">​</a></h4><p>这 5 个寄存器有两种物理寄存器，在快速中断模式下(FIQ)它们对应着 Rx_irq (x=8~12)物理寄存器，其他模式下对应着 Rx (8~12) 物理寄存器。 FIQ 是快速中断模式，看名字就是知道这个中断模式要求快速执行。 FIQ 模式下中断处理程序可以使用 R8~R12寄存器，因为FIQ 模式下的 R8~R12 是独立的，因此中断处理程序可以不用执行保存和恢复中断现场的指令，从而加速中断的执行过程。</p><h4 id="_2-2-r13-sp-stack-pointer" tabindex="-1">2.2 R13（SP，Stack Pointer） <a class="header-anchor" href="#_2-2-r13-sp-stack-pointer" aria-label="Permalink to &quot;2.2 R13（SP，Stack Pointer）&quot;">​</a></h4><p>备份寄存器 R13 一共有 8 个物理寄存器，其中一个是用户模式(User)和系统模式(Sys)共用的，剩下的 7 个分别对应 7 种不同的模式。 R13 也叫做 SP，用来做为<strong>栈指针</strong>。基本上每种模式都有一个自己的 R13 物理寄存器，应用程序会初始化 R13，使其指向该模式专用的栈地址，这就是常说的初始化 SP 指针。主要用于存储当前模式下的<strong>栈顶地址</strong>。</p><h4 id="_2-3-r14-lr-link-register" tabindex="-1">2.3 R14（LR，Link Register） <a class="header-anchor" href="#_2-3-r14-lr-link-register" aria-label="Permalink to &quot;2.3 R14（LR，Link Register）&quot;">​</a></h4><p>备份寄存器 R14 一共有 7 个物理寄存器，其中一个是用户模式(User)、系统模式(Sys)和超级监视模式(Hyp)所共有的，剩下的 6 个分别对应 6 种不同的模式。R14 也称为连接寄存器(LR)，LR 寄存器在 ARM 中主要用作如下两种用途：</p><p>（1）每种处理器模式使用 R14(LR)来存放当前子程序的返回地址，如果使用 BL 或者 BLX来调用子函数的话， R14(LR)被设置成该子函数的返回地址，在子函数中，将 R14(LR)中的值赋给 R15(PC)即可完成子函数返回，比如在子程序中可以使用如下代码：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MOV PC, LR @寄存器 LR 中的值赋值给 PC，实现跳转</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>或者可以在子函数的入口出将 LR 入栈 :</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PUSH {LR} @将 LR 寄存器压栈</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>在子函数的最后面出栈即可：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POP {PC} @ 将上面压栈的 LR 寄存器数据出栈给 PC 寄存器，严格意义上来讲应该是将</span></span>
<span class="line"><span>		 @ LR 赋给 PC，因为 3 级流水线，这里只是演示代码。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>总的来说就是执行跳转指令( BL/BLX )时， LR 会自动保存跳转指令下一条指令的地址，当程序需要返回时将 LR 的值复制到 PC 即可实现程序返回。</p><p>（2）当异常发生以后，该异常模式对应的 R14 寄存器被设置成该异常模式将要返回的地址，R14 也可以当作普通寄存器使用。</p><blockquote><p>LR 在 BL 和 IRQ 中断有何不同？</p><table><tbody><tr><td align="center" width="150px">BL</td><td align="left">当执行 BL 指令时，指令执行过程中处理器内部就会将 PC 寄存器的值拷贝到 LR 寄存器，然后再将 LR 寄存器中的值自减 4 ， 所以 LR 寄存器中保存的就是 BL 指令下一条指令的地址。</td></tr><tr><td align="center">IRQ中断</td><td align="left">当正在执行一条指令时产生了一个 IRQ 中断，执行这条指令过程中处理器不会保存返回地址，而是执行完成后才会保存 PC 寄存器中的值到 LR 寄存器，但发生 IRQ 时正在执行的指令在执行完成后 PC 的值又会自动增 4 ，所以对于 IRQ 来说 LR 中保存的是被中断打断的指令的下下条指令的地址。所以我们在写中断处理的时候要注意修正这个问题，否则就会少一条指令。</td></tr></tbody></table></blockquote><p>当执行跳转指令或产生异常时， LR 寄存器中不会凭空产生一个返回地址，其原理是当执行跳转指令或产生异常时，处理器内部会将 PC 寄存器中的值拷贝到 LR 寄存器中，然后再将 LR 寄存器中的值自减 4 。</p><h4 id="_2-4-r15-pc-program-counter" tabindex="-1">2.4 R15（PC,Program Counter） <a class="header-anchor" href="#_2-4-r15-pc-program-counter" aria-label="Permalink to &quot;2.4  R15（PC,Program Counter）&quot;">​</a></h4><p>程序计数器 R15 也叫做 PC，用于存储当前<strong>取址指令的地址</strong>。对于三级流水线的 ARM 处理器来说， R15 保存着当前执行的指令地址值加 8 个字节，这是因为 ARM 的流水线机制导致的。 ARM 处理器的 3 级流水线为：取指→译码→执行，这三级流水线循环执行，比如当前正在执行第一条指令的同时也对第二条指令进行译码，第三条指令也同时被取出存放在 R15（PC） 中。</p><p>我们以当前正在执行的指令作为参考点的话，也就是以第一条指令为参考点，此时 R15（PC)）中存放的就是第三条指令，换句话说就是 R15（PC)）总是指向当前正在执行的指令地址再加上 2 条指令的地址。对于 32 位的 ARM 处理器，每条指令是 4 个字节，所以有：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">R15</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (PC)值 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 当前执行的程序位置 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 个字节</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_3-程序状态寄存器-cpsr-和-spsr" tabindex="-1">3. 程序状态寄存器 CPSR 和 SPSR <a class="header-anchor" href="#_3-程序状态寄存器-cpsr-和-spsr" aria-label="Permalink to &quot;3. 程序状态寄存器 CPSR 和 SPSR&quot;">​</a></h3><p>程序状态寄存器 PSR 可以分成当前程序状态寄存器 CPSR 与备份程序状态寄存器 SPSR。</p><p>所有的处理器模式都共用一个 CPSR 物理寄存器，因此 CPSR 可以在任何模式下被访问。 CPSR 是当前程序状态寄存器，该寄存器包含了条件标志位、中断禁止位、当前处理器模式标志等一些状态位以及一些控制位。</p><p>但是所有的处理器模式都共用一个 CPSR 必然会导致冲突，为此，除了 User 和 Sys 这两个模式以外，其他 7 个模式每个都配备了一个专用的物理状态寄存器，叫做 SPSR (备份程序状态寄存器)，当特定的异常中断发生时，SPSR 寄存器用来保存当前程序状态寄存器(CPSR)的值，当异常退出以后可以用 SPSR 中保存的值来恢复 CPSR 。因为 User 和 Sys 这两个模式不是异常模式，所以并没有配备 SPSR ，因此不能在 User 和 Sys 模式下访问 SPSR ，会导致不可预知的结果。由于 SPSR 是 CPSR 的备份，因此 SPSR 和 CPSR 的寄存器结构相同。结构如下图所示：</p><img src="`+l+'" alt="image-20220727181412555" style="zoom:50%;"><ul><li><strong>N(bit31)</strong> ：当两个补码表示的有符号整数运算的时候， N=1 表示运算对的结果为负数， N=0 表示结果为正数。</li><li><strong>Z(bit30)</strong> ： Z=1 表示运算结果为零， Z=0 表示运算结果不为零，对于 CMP 指令， Z=1 表示进行比较的两个数大小相等。</li><li><strong>C(bit29)</strong> ：在加法指令中，当结果产生了进位，则 C=1 ，表示无符号数运算发生上溢，其它情况下 C=0 。在减法指令中，当运算中发生借位，则 C=0 ，表示无符号数运算发生下溢，其它情况下 C=1 。对于包含移位操作的非加减法运算指令， C 中包含最后一次溢出的位的数值，对于其它非加减运算指令， C 位的值通常不受影响。</li><li><strong>V(bit28)</strong> ：对于加减法运算指令，当操作数和运算结果表示为二进制的补码表示的带符号数时， V=1 表示符号位溢出，通常其他位不影响 V 位。</li><li><strong>Q(bit27)</strong> ：仅 ARM v5TE_J 架构支持，表示饱和状态， Q=1 表示累积饱和， Q=0 表示累积不饱和。</li><li><strong>IT[1:0](bit26:25)</strong> ：和 IT[7:2](bit15:bit10) 一起组成 IT[7:0] ，作为 IF-THEN 指令执行状态。</li><li><strong>J(bit24)</strong> ：控制指令执行状态，表明本指令是 ARM 指令还是Thumb 指令。仅 ARM_v5TE-J 架构支持， J=1 表示处于 Jazelle 状态，此位通常和 T(bit5) 位一起表示当前所使用的指令集。</li></ul><table><tbody><tr><td align="center" style="font-weight:bold;">J(bit24)</td><td align="center" style="font-weight:bold;">T(bit5)</td><td align="center" style="font-weight:bold;">指令类型</td></tr><tr><td align="center">0</td><td align="center">0</td><td align="center">ARM</td></tr><tr><td align="center">0</td><td align="center">1</td><td align="center">Thumb</td></tr><tr><td align="center">1</td><td align="center">1</td><td align="center">ThumbEE</td></tr><tr><td align="center">1</td><td align="center">0</td><td align="center">Jazelle</td></tr></tbody></table><ul><li><strong>GE[3:0](bit19)</strong> ： SIMD 指令有效，大于或等于。</li><li><strong>IT[7:2](bit15)</strong> ：参考 IT[1:0] 。</li><li><strong>E(bit9)</strong> ：大小端控制位， E=1 表示大端模式， E=0 表示小端模式。</li><li><strong>A(bit8)</strong> ： 禁止异步中断位， A=1 表示禁止异步中断。</li><li><strong>I(bit7)</strong> ： I=1 禁止 IRQ ， I=0 使能 IRQ 。</li><li><strong>F(bit6)</strong> ： F=1 禁止 FIQ ， F=0 使能 FIQ 。</li><li><strong>T(bit5)</strong> ： 控制指令执行状态，表明本指令是 ARM 指令还是 Thumb 指令，通常和 J(bit24) 一起使用表明指令类型，参考 J(bit24) 位。</li><li><strong>M[4:0]</strong> 处理器模式控制位， 取值与模式对应情况如下：</li></ul><table><tbody><tr><td align="center" style="font-weight:bold;">M[4:0]</td><td align="center" style="font-weight:bold;">处理器模式</td></tr><tr><td align="center">10000</td><td align="left">User模式</td></tr><tr><td align="center">10001</td><td align="left">FIQ模式</td></tr><tr><td align="center">10010</td><td align="left">IRQ模式</td></tr><tr><td align="center">10011</td><td align="left">Supervisor(SVC)模式</td></tr><tr><td align="center">10110</td><td align="left">Monitor(MON)模式</td></tr><tr><td align="center">10111</td><td align="left">Abort(ABT)模式</td></tr><tr><td align="center">11010</td><td align="left">Hyp(HYP)模式</td></tr><tr><td align="center">11011</td><td align="left">Undef(UND)模式</td></tr><tr><td align="center">11111</td><td align="left">System(SYS)模式</td></tr></tbody></table>',43)])])}const m=e(o,[["render",d]]);export{u as __pageData,m as default};
